from __future__ import annotations

import json
from pathlib import Path
from typing import Any


def _flatten(value: Any, prefix: str = "") -> dict[str, Any]:
    out: dict[str, Any] = {}
    if isinstance(value, dict):
        for key, child in value.items():
            name = f"{prefix}.{key}" if prefix else key
            out.update(_flatten(child, name))
    else:
        out[prefix] = value
    return out


def load_jsonl(path: str | Path) -> list[dict[str, Any]]:
    with Path(path).open(encoding="utf-8") as f:
        return [json.loads(line) for line in f if line.strip()]


def exact_field_accuracy(
    predictions: list[dict[str, Any]], gold: list[dict[str, Any]]
) -> dict[str, Any]:
    gold_by_id = {x["case_id"]: x for x in gold}
    predictions_by_id = {x["case_id"]: x for x in predictions}
    if len(gold_by_id) != len(gold) or len(predictions_by_id) != len(predictions):
        raise ValueError("Duplicate case IDs in predictions or gold labels")
    correct = 0
    total = 0
    case_scores: dict[str, float] = {}
    for case_id in gold_by_id:
        pred = predictions_by_id.get(case_id, {})
        p = _flatten(pred.get("structured_facts", {}))
        g = _flatten(gold_by_id[case_id].get("structured_facts", {}))
        case_correct = 0
        case_total = 0
        for key, expected in g.items():
            if expected is None:
                continue
            case_total += 1
            total += 1
            if key in p and type(p[key]) is type(expected) and p[key] == expected:
                case_correct += 1
                correct += 1
        case_scores[case_id] = (case_correct / case_total) if case_total else 1.0
    return {
        "field_accuracy": (correct / total) if total else 0.0,
        "correct_fields": correct,
        "evaluated_fields": total,
        "case_scores": case_scores,
        "case_coverage": len(set(predictions_by_id) & set(gold_by_id)) / len(gold_by_id)
        if gold_by_id
        else 0.0,
        "missing_case_ids": sorted(set(gold_by_id) - set(predictions_by_id)),
        "unexpected_case_ids": sorted(set(predictions_by_id) - set(gold_by_id)),
    }

case_intake/extractor.py.content:
from __future__ import annotations

import re
from pathlib import Path
from typing import Any

from .models import CaseIntakeResult, CategoryFacts


def _search_int(pattern: str, text: str) -> int | None:
    m = re.search(pattern, text, flags=re.I)
    return int(m.group(1)) if m else None


def _search_float(pattern: str, text: str) -> float | None:
    m = re.search(pattern, text, flags=re.I)
    return float(m.group(1)) if m else None


def _bool_from_patterns(text: str, positive: list[str], negative: list[str]) -> bool | None:
    # Explicit negation wins when both a symptom term and a denial appear in one sentence.
    for p in negative:
        if re.search(p, text, flags=re.I):
            return False
    for p in positive:
        if re.search(p, text, flags=re.I):
            return True
    return None


def _extract_demographics(text: str) -> dict[str, Any]:
    m = re.search(r"(\d{2})-year-old\s+(male|female)\s+([^\.]+)", text, flags=re.I)
    return {
        "age": int(m.group(1)) if m else None,
        "sex": m.group(2).lower() if m else None,
        "occupation": m.group(3).strip() if m else None,
    }


def _extract_vitals(text: str) -> dict[str, Any]:
    bp = re.search(r"BP\s*(\d{2,3})/(\d{2,3})\s*mmHg", text, flags=re.I)
    pulse = re.search(r"(?:pulse|HR)\s*(\d{2,3})\s*bpm", text, flags=re.I)
    return {
        "height_cm": _search_int(r"Height\s*(\d{2,3})\s*cm", text),
        "weight_kg": _search_float(r"weight\s*(\d+(?:\.\d+)?)\s*kg", text),
        "bmi": _search_float(r"BMI\s*(\d+(?:\.\d+)?)", text),
        "bp_systolic": int(bp.group(1)) if bp else None,
        "bp_diastolic": int(bp.group(2)) if bp else None,
        "pulse_bpm": int(pulse.group(1)) if pulse else None,
        "repeat_bp_available": False
        if re.search(r"No repeat BP is available", text, flags=re.I)
        else None,
    }


def _extract_cardiovascular(text: str) -> dict[str, Any]:
    chest_pain = _bool_from_patterns(
        text,
        [r"reports?\s+intermittent exertional chest pain", r"reports?[^\.]*chest pain"],
        [
            r"denies?[^\.]*chest pain",
            r"No current chest pain",
            r"No cardiac symptoms",
            r"Nil cardiac symptoms",
            r"Denies cardiac symptoms",
        ],
    )
    palpitations = _bool_from_patterns(
        text,
        [r"reports?[^\.]*palpitations"],
        [
            r"denies?[^\.]*palpitations",
            r"No current[^\.]*palpitations",
            r"No cardiac symptoms",
            r"Nil cardiac symptoms",
            r"Denies cardiac symptoms",
        ],
    )
    shortness = _bool_from_patterns(
        text,
        [r"reports?[^\.]*shortness of breath", r"reports?[^\.]*breathlessness"],
        [
            r"denies?[^\.]*(?:shortness of breath|breathlessness)",
            r"No current[^\.]*(?:shortness of breath|breathlessness)",
            r"No cardiac symptoms",
            r"Nil cardiac symptoms",
            r"Denies cardiac symptoms",
        ],
    )
    mi_history = _bool_from_patterns(
        text,
        [r"History of myocardial infarction", r"Previous myocardial infarction"],
        [r"No known myocardial infarction"],
    )
    cardiac_surgery = _bool_from_patterns(
        text,
        [r"cardiac surgery"],
        [
            r"No heart disease or cardiac surgery",
            r"No known myocardial infarction or cardiac surgery",
        ],
    )
    if cardiac_surgery is True and re.search(
        r"No (?:heart disease or |known myocardial infarction or )cardiac surgery", text, flags=re.I
    ):
        cardiac_surgery = False

    cardiac_history_present = None
    if re.search(r"No known cardiac history", text, flags=re.I):
        cardiac_history_present = False
    elif re.search(r"No heart disease", text, flags=re.I):
        cardiac_history_present = False
    elif mi_history is True:
        cardiac_history_present = True

    report_available = None
    report_type = None
    if re.search(r"recent cardiology report is available", text, flags=re.I):
        report_available = True
        report_type = "cardiology"
    elif re.search(r"No specialist report is available", text, flags=re.I):
        report_available = False
        report_type = "specialist"

    return {
        "chest_pain": chest_pain,
        "palpitations": palpitations,
        "shortness_of_breath": shortness,
        "cardiac_history_present": cardiac_history_present,
        "myocardial_infarction_history": mi_history,
        "myocardial_infarction_year": _search_int(r"myocardial infarction in\s+(\d{4})", text),
        "pci_or_coronary_stent": True
        if re.search(r"(?:PCI|angioplasty)[^\.]*stent|coronary stent", text, flags=re.I)
        else None,
        "cardiac_surgery_history": cardiac_surgery,
        "specialist_report_available": report_available,
        "specialist_report_type": report_type,
    }


def _acuity_pair(text: str, prefix: str = "") -> dict[str, str] | None:
    if prefix:
        pattern = rf"{prefix}[^\.]*?right eye\s*(6/\d+)[^\.]*?left eye\s*(6/\d+)"
    else:
        pattern = r"right eye\s*(6/\d+)[^\.]*left eye\s*(6/\d+)"
    m = re.search(pattern, text, flags=re.I)
    return {"right": m.group(1), "left": m.group(2)} if m else None


def _extract_vision(text: str) -> dict[str, Any]:
    unaided = _acuity_pair(text, "Unaided visual acuity")
    corrected = _acuity_pair(text, "corrected with glasses to")
    if corrected is None:
        m = re.search(
            r"corrected with glasses to right eye\s*(6/\d+)\s+and left eye\s*(6/\d+)",
            text,
            flags=re.I,
        )
        corrected = {"right": m.group(1), "left": m.group(2)} if m else None

    meets_standard = None
    if re.search(r"Vision:\s*Meets commercial driving standards", text, flags=re.I) or re.search(
        r"Vision meets commercial driving standards", text, flags=re.I
    ):
        meets_standard = True
    elif re.search(r"Vision:\s*WNL", text, flags=re.I):
        meets_standard = True

    correction = None
    if re.search(r"without correction|without corrective lenses", text, flags=re.I):
        correction = False
    if re.search(r"Vision:\s*WNL with glasses", text, flags=re.I) or re.search(
        r"corrected with glasses", text, flags=re.I
    ):
        correction = True

    diplopia = _bool_from_patterns(text, [r"Reports intermittent diplopia"], [r"No diplopia"])
    field_defect = True if re.search(r"visual field defect", text, flags=re.I) else None
    fields_normal = True if re.search(r"Visual fields normal", text, flags=re.I) else None
    optometrist_report_available = (
        False if re.search(r"No optometrist report is available", text, flags=re.I) else None
    )

    return {
        "meets_standard_statement": meets_standard,
        "correction_used": correction,
        "unaided_visual_acuity": unaided,
        "corrected_visual_acuity": corrected,
        "diplopia": diplopia,
        "visual_field_defect": field_defect,
        "visual_fields_normal": fields_normal,
        "optometrist_report_available": optometrist_report_available,
    }


def _extract_hearing(text: str) -> dict[str, Any]:
    normal_statement = None
    if re.search(
        r"Hearing:\s*(?:WNL|normal|Meets commercial driving standards)", text, flags=re.I
    ) or re.search(r"Audio:\s*WNL", text, flags=re.I):
        normal_statement = True

    hearing_loss = _bool_from_patterns(
        text,
        [r"Bilateral hearing loss", r"hearing loss in the left ear", r"Reports reduced hearing"],
        [r"no hearing loss"],
    )
    aids = _bool_from_patterns(
        text,
        [r"uses hearing aids", r"with hearing aids"],
        [
            r"without hearing aids",
            r"without aids",
            r"No hearing aids?\b",
            r"no hearing loss or hearing aids",
        ],
    )
    audiometry = _bool_from_patterns(
        text,
        [r"Audiometry completed"],
        [r"No audiometry or audiogram is available"],
    )
    audiologist_report_available = (
        False if re.search(r"No audiologist report is available", text, flags=re.I) else None
    )
    better_ear = _search_float(r"better ear average\s*(\d+(?:\.\d+)?)\s*dB", text)

    return {
        "normal_statement": normal_statement,
        "hearing_loss": hearing_loss,
        "hearing_aids_used": aids,
        "audiometry_completed": audiometry,
        "unaided_better_ear_average_db": better_ear,
        "audiologist_report_available": audiologist_report_available,
    }


def _extract_explicit_missing(text: str) -> list[str]:
    pairs = [
        (r"No repeat BP is available", "repeat_blood_pressure"),
        (r"No specialist report is available", "specialist_report"),
        (r"No optometrist report is available", "optometrist_report"),
        (r"No audiologist report is available", "audiologist_report"),
        (r"No audiometry or audiogram is available", "audiometry_or_audiogram"),
    ]
    return [name for pattern, name in pairs if re.search(pattern, text, flags=re.I)]


def _category_map(facts: dict[str, Any], missing: list[str]) -> list[CategoryFacts]:
    # Mapping is based only on which fact domains are present in the note.
    # It does not decide whether any standard is met.
    cv = {"vitals": facts["vitals"], "cardiovascular": facts["cardiovascular"]}
    vision = facts["vision"]
    hearing = facts["hearing"]
    return [
        CategoryFacts(
            category="cardiovascular",
            facts=cv,
            explicit_missing=[
                x for x in missing if x in {"repeat_blood_pressure", "specialist_report"}
            ],
        ),
        CategoryFacts(
            category="vision",
            facts=vision,
            explicit_missing=[x for x in missing if x == "optometrist_report"],
        ),
        CategoryFacts(
            category="hearing",
            facts=hearing,
            explicit_missing=[
                x for x in missing if x in {"audiologist_report", "audiometry_or_audiogram"}
            ],
        ),
    ]


def extract_case_text(text: str, case_id: str, source_document: str) -> CaseIntakeResult:
    clean = " ".join(text.strip().split())
    facts = {
        "demographics": _extract_demographics(clean),
        "vitals": _extract_vitals(clean),
        "cardiovascular": _extract_cardiovascular(clean),
        "vision": _extract_vision(clean),
        "hearing": _extract_hearing(clean),
    }
    missing = _extract_explicit_missing(clean)
    return CaseIntakeResult(
        case_id=case_id,
        source_document=source_document,
        structured_facts=facts,
        explicit_missing=missing,
        category_map=_category_map(facts, missing),
        notes=[
            "Fixture parser for the supplied SYN-M2 notes; production extraction remains an upstream component.",
            "Category mapping is non-diagnostic and does not determine fitness or RAG routing.",
        ],
    )


def extract_case_file(path: str | Path) -> CaseIntakeResult:
    path = Path(path)
    m = re.search(r"SYN-M2-(\d{3})", path.name, flags=re.I)
    case_id = f"SYN-M2-{m.group(1)}" if m else path.stem
    return extract_case_text(
        path.read_text(encoding="utf-8"), case_id=case_id, source_document=path.name
    )

case_intake/model_intake.py.content:
"""Local-model intake with deterministic grounding and explicit fallback provenance."""

from __future__ import annotations

import re

import pymupdf

from occupational_fitness_rag.case_intake.traceable import extract_traceable_text, valid_value
from occupational_fitness_rag.llm import OllamaClient
from occupational_fitness_rag.schemas.workflow import ClinicalCase, Fact, TextSpan


def same_value(left, right):
    if type(left) is bool or type(right) is bool:
        return type(left) is type(right) and left == right
    return left == right


def quote_supports(field, value, quote, specs):
    """Check meaning in a quote, not merely whether its characters occur in a note."""
    parsed = extract_traceable_text(quote, "GROUNDING", "quote.txt", specs)
    candidate = parsed.facts.get(field, Fact())
    if candidate.status != "unknown":
        return candidate.status == "present" and same_value(candidate.value, value)
    # Additional bounded language patterns let the model locate phrasing the
    # baseline parser does not select, without accepting arbitrary negation.
    patterns = {
        "diabetes.present": (
            r"(?:the patient |patient )?(?:denies|has no)(?: a)?(?: history of)? diabetes(?: mellitus)?[.!]?",
            False,
        ),
        "blackout.occurred": (
            r"(?:the patient |patient )?(?:denies|has no)(?: a)?(?: history of)? (?:blackouts?|loss of consciousness)[.!]?",
            False,
        ),
        "cardiovascular.blood_pressure.observed_systolic": (
            r"(?:blood pressure|bp) (?:was |is |measured at )?(\d+(?:\.\d+)?)\s*/\s*(\d+(?:\.\d+)?)(?:\s*mmhg)?[.!]?",
            "sbp",
        ),
        "cardiovascular.blood_pressure.observed_diastolic": (
            r"(?:blood pressure|bp) (?:was |is |measured at )?(\d+(?:\.\d+)?)\s*/\s*(\d+(?:\.\d+)?)(?:\s*mmhg)?[.!]?",
            "dbp",
        ),
    }
    if field not in patterns:
        return False
    pattern, meaning = patterns[field]
    match = re.fullmatch(pattern, quote.strip(), flags=re.I)
    if not match:
        return False
    expected = float(match[1 if meaning == "sbp" else 2]) if meaning in ("sbp", "dbp") else meaning
    return same_value(value, expected)


def apply_model_proposals(case, response, specs, page_ranges=()):
    facts = dict(case.facts)
    accepted, withheld = [], list(response.get("rejected", []))
    warnings = list(case.warnings)
    for proposal in response.get("proposals", []):
        field, value, quote = proposal["field"], proposal["value"], proposal["quote"]
        start = proposal.get("source_start")
        if start is None:
            start = case.source_text.find(quote) if quote else -1
        reason = None
        if field not in specs or not valid_value(field, value, specs):
            reason = "invalid_field_type_or_range"
        elif proposal.get("subject", "patient") != "patient":
            reason = "subject_is_not_patient"
        elif proposal.get("certainty", "explicit") != "explicit":
            reason = "statement_is_not_explicit"
        elif proposal.get("temporality") == "history" and (
            "blood_pressure" in field
            or field.startswith(("vision.", "hearing."))
            or field == "diabetes.treatment_category"
        ):
            reason = "historical_measurement_or_treatment_is_not_current"
        elif not quote or quote not in case.source_text:
            reason = "quote_not_in_input"
        elif (
            type(start) is not int
            or start < 0
            or case.source_text[start : start + len(quote)] != quote
        ):
            reason = "quote_offset_does_not_match_input"
        elif field == "diabetes.treatment_category" and re.search(
            r"not available for verification|awaiting verification|cannot be verified",
            re.split(r"[.!?;](?=\s|$)|\n", case.source_text[start:], maxsplit=1)[0],
            re.I,
        ):
            reason = "current_treatment_requires_verification"
        elif not quote_supports(field, value, quote, specs):
            reason = "value_not_supported_by_quote"
        elif re.search(
            r"\b(?:no|denies|without|negative for|family|mother|father|sister|brother|if|hypothetical)\b[^.;\n]{0,80}$",
            case.source_text[max(0, start - 100) : start],
            flags=re.I,
        ):
            reason = "quote_omits_possible_negation_or_subject_context"
        if reason:
            withheld.append({**proposal, "reason": reason})
            continue
        end = start + len(quote)
        span = TextSpan(
            start=start,
            end=end,
            quote=quote,
            line_start=case.source_text.count("\n", 0, start) + 1,
            line_end=case.source_text.count("\n", 0, end - 1) + 1,
            pdf_page=next((page for a, b, page in page_ranges if a <= start < b), None),
        )
        previous = facts.get(field, Fact())
        if previous.status in {"conflicting", "requires_confirmation"} or (
            previous.status == "present" and not same_value(previous.value, value)
        ):
            facts[field] = Fact(
                status="conflicting",
                evidence=[*previous.evidence, span],
                method="model_baseline_conflict",
                unit=specs[field].get("unit"),
                derived_from=previous.derived_from,
            )
            warnings.append(f"CONFLICTING_FACT:{field}")
            withheld.append({**proposal, "reason": "conflict_with_other_input_evidence"})
            continue
        facts[field] = Fact(
            value=value,
            status="present",
            unit=specs[field].get("unit"),
            evidence=[*previous.evidence, span],
            method="llm_grounded",
            derived_from=previous.derived_from,
        )
        accepted.append(field)
    # Re-validate every source span after merging; results remain machine-replayable.
    updated = ClinicalCase.model_validate(
        {
            **case.model_dump(),
            "facts": facts,
            "warnings": sorted(set(warnings)),
            "extraction_method": "local_llm_grounded_with_deterministic_fallback",
        }
    )
    return updated, {
        **response,
        "accepted_fields": sorted({key for key in accepted if facts[key].method == "llm_grounded"}),
        "withheld": withheld,
        "grounding_policy": "exact_quote_type_range_and_field_semantics_v1",
        "status": "completed" if accepted else "completed_no_grounded_fields",
        "authoritative_facts_modified": bool(accepted),
    }


def model_intake(case, specs, config, page_ranges=()):
    if not config.enabled or not config.extraction_enabled:
        return case, {"status": "disabled", "accepted_fields": []}
    client = OllamaClient(config)
    try:
        response = client.extract(case.source_text, specs, case.modules_requested)
        return apply_model_proposals(case, response, specs, page_ranges)
    except Exception as exc:
        updated = ClinicalCase.model_validate(
            {
                **case.model_dump(),
                "extraction_method": "deterministic_fallback",
                "warnings": [*case.warnings, "LOCAL_MODEL_UNAVAILABLE:deterministic_fallback"],
            }
        )
        return updated, {
            "status": "unavailable_fallback_to_template",
            "model": config.model,
            "error_type": type(exc).__name__,
            "accepted_fields": [],
        }


def pdf_ranges(path):
    ranges, offset = [], 0
    if path.suffix.lower() == ".pdf":
        with pymupdf.open(path) as doc:
            for number, page in enumerate(doc, 1):
                text = page.get_text(sort=True)
                ranges.append((offset, offset + len(text), number))
                offset += len(text) + 1
    return ranges

case_intake/narrative_context.py.content:
"""Select bounded verbatim symptom passages for retrieval, never for rule facts.

This conservative vocabulary extends the field dictionary with common nurse-note
phrasing. Matching selects review context; it does not diagnose a condition,
resolve negation or confirm a measurement. Mixed passages may match two modules.
"""

import re

from occupational_fitness_rag.schemas.workflow import TextSpan

MODULE_TERMS = {
    "hypertension": r"blood[- ]pressure|\bbp\b|hypertens|antihypertensive|pressure tablets",
    "vision": r"vis(?:ion|ual)|\beye\b|optometr|diplopia|double|two overlapping|headlights|blur|scotoma|monocular",
    "hearing": r"hear|audiom|audiolog|\bear\b|\bdb\b|dispatch|doorbell|spoken|radio instructions",
    "blackout": r"blackout|syncope|faint|collapse|unresponsive|consciousness|(?:loss of|lost|altered|impaired) awareness|blank spell|seizure",
    "diabetes": r"diabet|insulin|glucose|glycaem|glycem|endocrin|metabolic|thirst|pass urine",
}


CONTEXT_VERSION = 2
LEGACY_BLACKOUT_TERMS = (
    r"blackout|syncope|faint|collapse|unresponsive|consciousness|awareness|blank spell|seizure"
)


def select_narrative_context(case, requests, rules, *, version=CONTEXT_VERSION):
    """Return module-scoped source spans, excluding structured addendum lines.

    Selection is deterministic and bounded to 2,000 characters per module. Entire
    sentences retain uncertainty, negation, subject and timing. Oversized single
    sentences are omitted rather than cut into misleading partial quotations.
    """
    if version not in {1, CONTEXT_VERSION}:
        raise ValueError("Unsupported narrative context version")
    selected = {}
    for module in case.modules_requested:
        spans, budget = [], 2000
        pattern = (
            LEGACY_BLACKOUT_TERMS if module == "blackout" and version == 1 else MODULE_TERMS[module]
        )
        for match in re.finditer(r"[^\n]+", case.source_text):
            if re.match(r"[a-z][a-z0-9_.]+\s*=", match[0]):
                continue
            for sentence in re.finditer(r".+?(?:[.!?](?=\s|$)|$)", match[0]):
                quote = sentence[0]
                leading = len(quote) - len(quote.lstrip())
                quote = quote.strip()
                if not quote or not re.search(pattern, quote, re.I) or len(quote) > budget:
                    continue
                start = match.start() + sentence.start() + leading
                end = start + len(quote)
                spans.append(
                    TextSpan(
                        start=start,
                        end=end,
                        quote=quote,
                        line_start=case.source_text.count("\n", 0, start) + 1,
                        line_end=case.source_text.count("\n", 0, end - 1) + 1,
                    ).model_dump(mode="json")
                )
                budget -= len(quote)
        selected[module] = spans
    return {
        request.request_id: selected[rules[request.rule_id]["module"]]
        for request in requests
        if selected[rules[request.rule_id]["module"]]
    }

