    (output / "index.html").write_text(html, encoding="utf-8")
    return summary


def validate_saved_rows(rows, manifest, frozen):
    """Do not resume from edited condition identities, labels or accepted stage records."""
    planned = {tuple(key) for key in manifest["planned_keys"]}
    keys = [previous.condition_key(row) for row in rows]
    if len(keys) != len(set(keys)) or not set(keys) <= planned:
        raise ValueError("Duplicate or unexpected saved condition")
    for row in rows:
        selected = frozen["payloads"][row["case_id"]][row["evidence_policy"]]
        if (
            row["experiment_identity"] != manifest["identity"]
            or row["model_digest"] != manifest["environment"]["model_digests"][row["model"]]
            or row["reference_outcome"] != frozen["labels"][row["case_id"]]
            or row["input_sha256"] != selected.get("input_sha256", digest(selected))
            or row["status"] not in {"completed", "failed"}
        ):
            raise ValueError("Saved condition identity, input or reference changed")
        if selected["status"] == "completed" and row.get("input_snapshot") != selected["payload"]:
            raise ValueError("Saved patient input snapshot changed")
        stages = row.get("stages", {})
        for stage in stages.values():
            for attempt in stage["attempts"]:
                if attempt["request_sha256"] != digest(attempt["request"]) or attempt[
                    "request_bytes"
                ] != len(previous.json_bytes(attempt["request"])):
                    raise ValueError("Saved stage request fingerprint changed")
                if attempt["status"] == "completed" and "error" in attempt:
                    raise ValueError("Accepted stage attempt carries a failure")
        if row["model_attempts"] != sum(len(stage["attempts"]) for stage in stages.values()):
            raise ValueError("Saved stage cost differs from its attempts")
        if row["model_calls"] != sum(
            bool(attempt.get("provider_called"))
            for stage in stages.values()
            for attempt in stage["attempts"]
        ):
            raise ValueError("Saved provider-call cost differs from its stage records")
        if row["status"] == "completed":
            final = stages[
                "outcome_first" if row["protocol"] == "passage_selection" else "aggregation"
            ]
            if (
                final["status"] != "completed"
                or row["answer"] != final["answer"]
                or row["attempts"] != final["attempts"]
                or "error" in row
                or not row["reference_agreement"]
                == (row["answer"]["assessment_outcome"] == row["reference_outcome"])
            ):
                raise ValueError("Saved accepted proposal differs from its final stage")
        elif row["reference_agreement"]:
            raise ValueError("A failed condition cannot agree with a reference")


def run_comparison(
    config_path,
    resume=False,
    max_conditions=None,
    post=local_post,
    get=previous.local_get,
    api=None,
):
    if max_conditions is not None and (type(max_conditions) is not int or max_conditions < 0):
        raise ValueError("max_conditions must be a non-negative integer")
    config_path = Path(config_path)
    config_text = config_path.read_text(encoding="utf-8")
    config = yaml.safe_load(config_text)
    validate_config(config)
    output, upstream = Path(config["output"]).resolve(), Path(config["retrieval_dir"]).resolve()
    if output == upstream or output.is_relative_to(upstream) or upstream.is_relative_to(output):
        raise ValueError("New experiment output must be isolated from frozen retrieval")
    previous.read_records(output / "results.jsonl")
    frozen = load_retrieval(config)
    environment = previous.pinned_environment(config, get)
    sources = previous.source_snapshot(config_text)
    planned = list(
        product(
            config["models"],
            config["case_ids"],
            config["evidence_policies"],
            config["protocols"],
            range(config["repeats"]),
        )
    )
    identity_data = {
        "config": config,
        "config_sha256": sha256_bytes(config_text.encode("utf-8")),
        "sources_sha256": digest(sources),
        "upstream_fingerprints": frozen["fingerprints"],
        "environment": environment,
        "planned_keys": planned,
    }
    manifest = {
        **identity_data,
        "identity": digest(identity_data),
        "planned_conditions": len(planned),
        "corpus_sha256": config["expected_corpus_sha256"],
        "phase": config.get("phase", "known_error_development_set"),
        "clinical_review": "pending",
        "production_change": False,
    }
    output.mkdir(parents=True, exist_ok=True)
    lock = output / ".run.lock"
    try:
        with lock.open("x", encoding="ascii") as stream:
            stream.write(str(os.getpid()))
    except FileExistsError as exc:
        raise ValueError("Another run or an unreviewed stale run lock exists") from exc
    try:
        path = output / "manifest.json"
        artifacts = {
            "source_snapshot.json": sources,
            "retrieval_inputs.json": frozen["payloads"],
            "corpus.json": frozen["corpus"],
            "reference_labels.json": frozen["labels"],
            "upstream_manifest.json": frozen["manifest"],
        }
        if path.exists():
            if not resume:
                raise ValueError("Existing experiment requires --resume or a new output")
            if json.loads(path.read_text(encoding="utf-8")) != json.loads(json.dumps(manifest)):
                raise ValueError(
                    "Experiment identity changed; preserve output and use a new directory"
                )
            for name, value in artifacts.items():
                if json.loads((output / name).read_text(encoding="utf-8")) != json.loads(
                    json.dumps(value)
                ):
                    raise ValueError("Saved experiment artifact changed: " + name)
        else:
            if any(item.name != ".run.lock" for item in output.iterdir()):
                raise ValueError("Non-empty output lacks a manifest")
            write_json(path, manifest)
            for name, value in artifacts.items():
                write_json(output / name, value)
        rows = previous.read_records(output / "results.jsonl")
        validate_saved_rows(rows, manifest, frozen)
        planned_keys = set(planned)
        write_report(output, rows, planned_keys)
        done = {previous.condition_key(row) for row in rows}
        added = 0
        for model, case_id, policy, protocol, repeat in planned:
            key = (model, case_id, policy, protocol, repeat)
            if key in done:
                continue
            if max_conditions is not None and added >= max_conditions:
                break
            previous.pinned_environment(config, get)
            selected = frozen["payloads"][case_id][policy]
            row = {
                "model": model,
                "model_digest": environment["model_digests"][model],
                "case_id": case_id,
                "evidence_policy": policy,
                "protocol": protocol,
                "repeat": repeat,
                "experiment_identity": manifest["identity"],
                "input_sha256": selected.get("input_sha256", digest(selected)),
            }
            if selected["status"] != "completed":
                row.update(
                    status="failed",
                    error="Frozen retrieval failed: " + selected["error"],
                    attempts=[],
                    stages={},
                    model_attempts=0,
                    model_calls=0,
                    seconds=0.0,
                    first_pass_status="failed",
                )
            else:
                row["selection"] = deepcopy(selected["selection"])
                if protocol == "passage_selection":
                    row.update(run_baseline(config, model, selected["payload"], post))
                else:
                    row.update(run_applicability(config, model, selected["payload"], post, api))
            # Labels are attached only after all model stages finish.
            row["reference_outcome"] = frozen["labels"][case_id]
            row["reference_agreement"] = row["status"] == "completed" and (
                row["answer"]["assessment_outcome"] == row["reference_outcome"]
            )
            if previous.read_records(output / "results.jsonl") != rows:
                raise ValueError("Records changed during the exclusive experiment")
            with (output / "results.jsonl").open("a", encoding="utf-8") as stream:
                stream.write(json.dumps(row, ensure_ascii=False, allow_nan=False) + "\n")
            rows.append(row)
            done.add(key)
            added += 1
            write_report(output, rows, planned_keys)
            print(
                f"Recorded {len(rows)}/{len(planned)}: {case_id} {model} {policy} {protocol} {row['status']}",
                flush=True,
            )
        return write_report(output, rows, planned_keys)
    finally:
        lock.unlink()


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--config", default="configs/experiments/applicability_comparison_bound.yaml"
    )
    parser.add_argument("--resume", action="store_true")
    parser.add_argument("--max-conditions", type=int)
    args = parser.parse_args()
    print(json.dumps(run_comparison(args.config, args.resume, args.max_conditions), indent=2))

evaluation/comparison_cost_audit.py.content:
"""Extract framework-reported request counters without inferring calls from caches."""

import argparse
import json
import re
from pathlib import Path

from occupational_fitness_rag.provenance import sha256_bytes, write_json


def audit_costs(output: Path):
    reports = []
    warnings = 0
    for path in sorted((output / "indexes").rglob("indexing-engine.log")):
        text = path.read_text(encoding="utf-8")
        warnings += text.count("Reached token limit - reverting to previous context state")
        for match in re.finditer(r"Metrics for ([^\n]+?): (\{.*?\n\})", text, re.DOTALL):
            metrics = json.loads(match.group(2))
            reports.append(
                {
                    "provider_model": match.group(1),
                    "metrics": metrics,
                    "log_path": str(path.relative_to(output)),
                    "log_sha256": sha256_bytes(path.read_bytes()),
                    "scope": "Framework provider counters emitted at worker shutdown",
                }
            )
    # One worker process emits cumulative provider metrics. Summing duplicate
    # snapshots would inflate request counts, so refuse ambiguous logs.
    names = [r["provider_model"] for r in reports]
    unambiguous = len(names) == len(set(names))
    chat = [r for r in reports if r["provider_model"].startswith("ollama_chat/")]
    result = {
        "graphrag": {
            "reports": reports,
            "attempted_graph_model_requests": sum(
                r["metrics"]["attempted_request_count"] for r in chat
            )
            if reports and unambiguous
            else None,
            "status": "framework_reported"
            if reports and unambiguous
            else "unavailable_or_ambiguous",
            "context_budget_warnings": warnings,
            "warning_interpretation": "Local graph context was budget-limited; this is not a failed source mapping or silent fallback",
        },
        "lightrag": {
            "attempted_graph_model_requests": None,
            "status": "Exact network attempts unavailable; cache entries are not request counters",
        },
    }
    write_json(output / "framework_cost_audit.json", result)
    return result


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("output", type=Path)
    print(json.dumps(audit_costs(parser.parse_args().output), indent=2))

evaluation/comparison_snapshot.py.content:
"""Export recorded experimental evidence into an existing Data report snapshot."""

import argparse
import json
from collections import Counter
from datetime import UTC, datetime
from pathlib import Path


def read_recorded_rows(path: Path):
    """Read only newline-terminated records while another process appends UTF-8."""
    rows = []
    if path.exists():
        for line in path.read_bytes().splitlines(keepends=True):
            if not line.endswith(b"\n"):
                continue
            rows.append(json.loads(line.decode("utf-8")))
    return rows


def update_snapshot(experiment: Path, snapshot_path: Path, checkpoint=None):
    snapshot = json.loads(snapshot_path.read_text(encoding="utf-8-sig"))
    corpus = json.loads((experiment / "corpus.json").read_text(encoding="utf-8"))
    snapshot["queries"]["corpus"]["rows"] = [
        {
            "source_id": u["source_id"],
            "module": u["module"],
            "section": u["section"],
            "pdf_page": u["pdf_page"],
            "text": u["evidence_text"],
        }
        for u in corpus["units"]
    ]
    definitions = {
        "corpus": (
            "corpus.json",
            "PDF-region-verified original passages; clinician review pending",
        ),
        "judgments": (
            "results.jsonl",
            "Recorded local model calls, actual supplied evidence and failures",
        ),
        "metrics": (
            "summary.json",
            "Recorded-call agreement and Macro-F1; failures remain in denominators",
        ),
        "transitions": (
            "summary.json",
            "Same-case, same-model and same-repeat changes relative to hybrid",
        ),
    }
    for query, (filename, definition) in definitions.items():
        snapshot["queries"][query]["source"] = {
            "title": filename,
            "provider": "Local experiment files",
            "description": definition,
            "links": [],
            "evidenceFlow": [
                {"title": "Recorded artifact", "detail": str((experiment / filename).resolve())},
                {
                    "title": "Frozen corpus fingerprint",
                    "detail": corpus.get("corpus_sha256", "Unavailable"),
                },
            ],
        }
    upstream_path = experiment / "upstream_audit.json"
    if upstream_path.exists():
        upstream = json.loads(upstream_path.read_text(encoding="utf-8"))
        snapshot["queries"]["upstream"] = {
            "rows": upstream["cases"],
            "payloadColumns": ["changed_fields"],
            "source": {
                "title": "Upstream fact review audit",
                "provider": "Local experiment files",
                "description": "Deterministic and frozen-rule outcomes; frozen inputs were not changed",
                "links": [],
                "evidenceFlow": [
                    {"title": "Recorded artifact", "detail": str(upstream_path.resolve())}
                ],
            },
        }
    summary_path = experiment / "summary.json"
    summary = (
        checkpoint
        if checkpoint is not None
        else (json.loads(summary_path.read_text(encoding="utf-8")) if summary_path.exists() else {})
    )
    rows = []
    path = experiment / "results.jsonl"
    if path.exists():
        recorded = read_recorded_rows(path)
        for row in recorded[: summary.get("recorded_runs", len(recorded))]:
            answer = row.get("answer", {})
            prediction = answer.get("assessment_outcome")
            error_type = (
                "failed"
                if row["status"] != "completed"
                else "none"
                if row.get("reference_agreement")
                else "excess_abstention"
                if prediction == "insufficient_information"
                else "reference_mismatch"
            )
            rows.append(
                dict(
                    {
                        key: value
                        for key, value in row.items()
                        if key not in {"raw_response", "input_snapshot"}
                    },
                    prediction=prediction,
                    error_type=error_type,
                    explanation=answer.get("explanation", ""),
                    cited_sources=", ".join(answer.get("source_ids", [])),
                    nurse_note=row["input_snapshot"]["nurse_note"],
                    facts_json=json.dumps(
                        row["input_snapshot"]["verified_patient_facts"], indent=2
                    ),
                    evidence_json=json.dumps(row["input_snapshot"]["guideline_evidence"], indent=2),
                )
            )
    snapshot["queries"]["judgments"]["rows"] = rows
    snapshot["queries"]["judgments"]["payloadColumns"] = ["facts_json", "evidence_json"]
    snapshot["queries"]["metrics"]["rows"] = summary.get("metrics", [])
    snapshot["queries"]["transitions"]["rows"] = summary.get("paired_transitions", [])
    completion_path = experiment / "completion_audit.json"
    if completion_path.exists():
        completion = json.loads(completion_path.read_text(encoding="utf-8"))
        for query, field, description in [
            (
                "classification_balance",
                "metrics",
                "Independent recalculation of agreement, reference-class recall and abstention baseline",
            ),
            (
                "paired_intervals",
                "paired_differences",
                "Case-clustered agreement differences relative to hybrid; failures remain misses",
            ),
        ]:
            snapshot["queries"][query] = {
                "rows": completion[field],
                "source": {
                    "title": "Completed comparison audit",
                    "provider": "Local experiment files",
                    "description": description,
                    "links": [],
                    "evidenceFlow": [
                        {"title": "Recorded artifact", "detail": str(completion_path.resolve())}
                    ],
                },
            }
    audit_path = experiment / "error_audit.json"
    if audit_path.exists():
        audit = json.loads(audit_path.read_text(encoding="utf-8"))
        for query, field, description in [
            (
                "error_pairs",
                "pairs",
                "Paired outcomes, exact evidence bundle differences and upstream review flags",
            ),
            (
                "repeat_stability",
                "repeat_stability",
                "Outcome stability requires all planned calls and identical inputs",
            ),
        ]:
            snapshot["queries"][query] = {
                "rows": audit[field],
                "source": {
                    "title": "Judgment error audit",
                    "provider": "Local experiment files",
                    "description": description,
                    "links": [],
                    "evidenceFlow": [
                        {"title": "Recorded artifact", "detail": str(audit_path.resolve())}
                    ],
                },
            }
    cost_path = experiment / "costs.json"
    if cost_path.exists():
        costs = json.loads(cost_path.read_text(encoding="utf-8"))
        cost_rows = []
        for retrieval in costs["retrieval"]:
            method = retrieval["method"]
            indexes = [r for r in costs["indexes"] if method in Path(r["index_path"]).parts]
            counters = (costs.get("framework_reported_counters") or {}).get(method, {})
            conditions = [r for r in rows if r["method"] == method]
            cost_rows.append(
                {
                    **retrieval,
                    "index_seconds": sum(r["seconds"] for r in indexes) if indexes else None,
                    "construction_scope": "Original cached incremental construction"
                    if any(r.get("llm_cache_reused") for r in indexes)
                    else "Original construction"
                    if indexes
                    else "Shared embedding cost not allocated",
                    "graph_model_requests": counters.get("attempted_graph_model_requests"),
                    "recorded_judgments": len(conditions),
                    "network_attempts": sum("request_sha256" in r for r in conditions),
                    "judgment_failures": sum(r["status"] != "completed" for r in conditions),
                    "judgment_seconds": sum(r["seconds"] for r in conditions),
                }
            )
        snapshot["queries"]["costs"] = {
            "rows": cost_rows,
            "source": {
                "title": "Retrieval and model cost audit",
                "provider": "Local experiment files",
                "description": "Recorded timing and framework-reported counters; unavailable counts remain null",
                "links": [],
                "evidenceFlow": [
                    {"title": "Recorded artifact", "detail": str(cost_path.resolve())}
                ],
            },
        }
    snapshot["status"] = summary.get("execution_status", "running")
    snapshot["plannedRuns"] = summary.get("planned_runs")
    labels_path = experiment / "labels.json"
    if labels_path.exists():
        labels = json.loads(labels_path.read_text(encoding="utf-8"))
        snapshot["cohortCounts"] = dict(Counter(label["cohort"] for label in labels))
    snapshot["buildStatus"] = "complete"
    snapshot["generatedAt"] = datetime.now(UTC).isoformat()
    temp = snapshot_path.with_suffix(".tmp")
    temp.write_text(json.dumps(snapshot, ensure_ascii=False, indent=2), encoding="utf-8")
    temp.replace(snapshot_path)
    return len(rows)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("experiment", type=Path)
    parser.add_argument("snapshot", type=Path)
    args = parser.parse_args()
    print(update_snapshot(args.experiment, args.snapshot))

evaluation/evidence_judgment.py.content:
"""Experimental clause-linked judgments, isolated from production decisions."""

import json
import re
from typing import Literal

from pydantic import Field

from occupational_fitness_rag.evaluation.judgment_comparison import (
    SYSTEM,
    judgment_request,
    validate_answer,
)
from occupational_fitness_rag.evaluation.model_judgment import ExperimentalJudgment
from occupational_fitness_rag.schemas.workflow import Contract

PROTOCOL_SYSTEM = (
    SYSTEM.replace(
        "Return the requested JSON with assessment_outcome, explanation, source_ids and\nfact_fields. Cite only supplied IDs and fields.",
        "Return assessment_outcome, explanation and criterion_checks. Cite only supplied IDs and fields in those checks.",
    )
    + """

Apply the following output-category meanings to the supplied original evidence:
- meets_unconditional_standard: the applicable unconditional requirements are supported;
  do not infer that unknown patient findings are normal.
- may_meet_conditional_standard: the evidence allows a conditional standard and the
  patient facts establish the relevant prerequisites, not just a treatment name.
- temporarily_unfit: an applicable current restriction requires stopping driving
  pending investigation, recovery or stabilisation. Unknown information in another
  module does not erase an already established current restriction.
- does_not_meet_standard: supplied applicable evidence explicitly excludes both
  unconditional AND conditional current eligibility. Failure of an unconditional
  criterion alone does not prove failure of every conditional pathway. This
  category does not itself mean permanent disqualification.
- insufficient_information: no stronger supported restrictive conclusion can be
  established and required facts or applicable guideline evidence are missing.

Record short criterion_checks linking a verified patient finding to a specific
guideline clause. These are auditable findings, not a request for private reasoning.
For every check, copy a SHORT contiguous guideline_quote verbatim from the selected
source_text. Preserve its words, punctuation and qualifications. Use only the
requested modules, supplied source IDs and verified fact fields. A quote describes
a criterion; it does not establish that the patient's criterion is met. Explicitly
distinguish established_restriction, conditional_permission, not_established and
information_missing. Established restrictions require at least one verified fact.
For each check, state whether the clause concerns unconditional licensing,
conditional licensing, both pathways, temporary no-driving, or general information.
Do not apply an undiagnosed-blackout investigation rule when verified facts establish
a diagnosed cause; use the applicable supplied cause-specific evidence or abstain.
The application derives final citation lists from your explicit criterion checks;
do not repeat source_ids or fact_fields as top-level lists. A proposed
conditional permission does not override an independently established restriction.
Do not use unverified original-note claims to fill missing verified facts. Do not
treat the failure to establish a conditional licence as proof of a permanent ban.
Return the same provisional outcome and explanation plus 1 to 5 criterion_checks.
"""
)


class CriterionCheck(Contract):
    module: Literal["hypertension", "vision", "hearing", "blackout", "diabetes"]
    source_id: str
    guideline_quote: str = Field(min_length=12, max_length=800)
    fact_fields: list[str] = Field(max_length=8)
    licence_pathway: Literal[
        "unconditional", "conditional", "both", "temporary_no_driving", "general_information"
    ]
    finding: Literal[
        "established_restriction",
        "conditional_permission",
        "not_established",
        "information_missing",
    ]
    conclusion: str = Field(min_length=1, max_length=500)


class EvidenceJudgment(ExperimentalJudgment):
    criterion_checks: list[CriterionCheck] = Field(min_length=1, max_length=5)


class ClauseJudgment(Contract):
    assessment_outcome: Literal[
        "meets_unconditional_standard",
        "may_meet_conditional_standard",
        "temporarily_unfit",
        "does_not_meet_standard",
        "insufficient_information",
    ]
    explanation: str = Field(min_length=1, max_length=2000)
    criterion_checks: list[CriterionCheck] = Field(min_length=1, max_length=5)


def normalized_quote(value):
    """Permit PDF line wrapping, never changed wording or punctuation."""
    return re.sub(r"\s+", " ", value).strip()


def quote_locations(quote, original):
    """Return every original character span; repeated quotes remain ambiguous."""
    if not normalized_quote(quote):
        return []
    pattern = re.escape(normalized_quote(quote)).replace(r"\ ", r"\s+")
    return [
        {"char_start": match.start(), "char_end": match.end(), "original_quote": match.group()}
        for match in re.finditer(pattern, original)
    ]


def criterion_locations(answer, payload):
    sources = {source["source_id"]: source for source in payload["guideline_evidence"]}
    return [
        {
            "source_id": check.source_id,
            "pdf_page": sources[check.source_id]["pdf_page"],
            "section": sources[check.source_id]["section"],
            "spans": quote_locations(
                check.guideline_quote, sources[check.source_id]["source_text"]
            ),
            "check": check.model_dump(mode="json"),
            "support_review": "pending_independent_review",
        }
        for check in answer.criterion_checks
    ]


def build_request(config, model, payload, protocol):
    body = judgment_request(config, model, payload)
    if protocol == "baseline":
        return body
    if protocol != "evidence_contract":
        raise ValueError("Unknown judgment protocol")
    sources = [s["source_id"] for s in payload["guideline_evidence"]]
    if not sources:
        raise ValueError("Clause-linked judgment requires original guideline evidence")
    schema = ClauseJudgment.model_json_schema()
    check = schema["$defs"]["CriterionCheck"]["properties"]
    check["module"]["enum"] = payload["modules"]
    check["source_id"]["enum"] = sources
    fields = list(payload["verified_patient_facts"])
    if fields:
        check["fact_fields"]["items"] = {"type": "string", "enum": fields}
        check["fact_fields"]["maxItems"] = min(len(fields), 8)
    else:
        check["fact_fields"]["maxItems"] = 0
    body["format"] = schema
    body["messages"][0]["content"] = PROTOCOL_SYSTEM
    return body


def validate_protocol_answer(answer, payload, protocol):
    validate_answer(answer, payload, "evidence_contract")
    if protocol == "baseline":
        return
    if protocol != "evidence_contract" or not isinstance(answer, EvidenceJudgment):
        raise ValueError("Wrong judgment protocol contract")
    sources = {source["source_id"]: source for source in payload["guideline_evidence"]}
    for check in answer.criterion_checks:
        source = sources.get(check.source_id)
        if check.module not in payload["modules"] or source is None:
            raise ValueError("Criterion check cites an unprovided module or source")
        if check.source_id not in answer.source_ids:
            raise ValueError("Criterion source is absent from the final citation list")
        if not set(check.fact_fields) <= set(answer.fact_fields):
            raise ValueError("Criterion facts are absent from the final fact list")
        if not set(check.fact_fields) <= set(payload["verified_patient_facts"]):
            raise ValueError("Criterion check cites an unverified patient fact")
        if check.finding == "established_restriction" and not check.fact_fields:
            raise ValueError("An established restriction requires a verified patient fact")
        if len(normalized_quote(check.guideline_quote)) < 12 or normalized_quote(
            check.guideline_quote
        ) not in normalized_quote(source["source_text"]):
            raise ValueError("Criterion quote does not match the original guideline passage")
        if any("\u3400" <= c <= "\u9fff" for c in check.conclusion):
            raise ValueError("Criterion conclusion must be in English")


def parse_response(raw, payload, protocol):
    if raw.get("done_reason") == "length" or raw.get("done") is False:
        raise ValueError("Model output was incomplete; partial answers rejected")
    if protocol == "baseline":
        answer = ExperimentalJudgment.model_validate_json(raw["message"]["content"])
    else:
        proposed = ClauseJudgment.model_validate_json(raw["message"]["content"])
        cited_sources = {check.source_id for check in proposed.criterion_checks}
        cited_facts = {field for check in proposed.criterion_checks for field in check.fact_fields}
        answer = EvidenceJudgment.model_validate(
            {
                **proposed.model_dump(mode="json"),
                "source_ids": [
                    source["source_id"]
                    for source in payload["guideline_evidence"]
                    if source["source_id"] in cited_sources
                ],
                "fact_fields": [
                    field for field in payload["verified_patient_facts"] if field in cited_facts
                ],
            }
        )
    validate_protocol_answer(answer, payload, protocol)
    return answer


def payload_size(payload):
    return len(json.dumps(payload, ensure_ascii=False).encode("utf-8"))

evaluation/evidence_selection.py.content:
"""Experimental evidence allocation using documented fact presence only.

This helper does not retrieve, interpret a diagnosis, or change the requested
assessment scope. Original-passage byte limits remain the caller's responsibility.
"""

from collections.abc import Mapping, Sequence
from typing import Any

MODULES = frozenset({"hypertension", "vision", "hearing", "blackout", "diabetes"})


def _documented_module(field: str, fact: Any):
    if not isinstance(fact, Mapping) or fact.get("value") is None:
        return None
    if fact.get("status", "present") != "present":
        return None
    prefix = field.split(".", 1)[0]
    return "hypertension" if prefix == "cardiovascular" else prefix


def select_documented_evidence(payload, rankings, top_k=5):
    """Allocate existing ranked source IDs without consulting reference labels.

    ``rankings`` contains one row per requested module, with ``module`` and
    ``source_ids``. Optional status must be ``completed``. When documented facts
    exist, only those modules receive evidence slots. Otherwise every requested
    module participates. Neither case asserts that an unmeasured module is normal.
    False and zero are documented values, not missing values. The function never
    mutates ``payload`` or the within-module rankings.
    """
    if isinstance(top_k, bool) or not isinstance(top_k, int) or top_k < 0:
        raise ValueError("top_k must be a non-negative integer")
    requested = list(dict.fromkeys(payload["modules"]))
    if set(requested) - MODULES:
        raise ValueError("Unknown requested assessment module")
    documented = {
        _documented_module(field, fact) for field, fact in payload["verified_patient_facts"].items()
    }
    documented_modules = [module for module in requested if module in documented]
    unmeasured_modules = [module for module in requested if module not in documented]
    active = documented_modules or requested
    ordered = {}
    for row in rankings:
        module = row["module"]
        if module not in requested:
            raise ValueError("Ranking module is outside the requested assessment scope")
        if module in ordered:
            raise ValueError("Provide exactly one ranking per module")
        if row.get("status", "completed") != "completed":
            raise ValueError("Failed retrieval cannot be used as a successful ranking")
        ids = row["source_ids"]
        if isinstance(ids, (str, bytes)) or not isinstance(ids, Sequence):
            raise ValueError("Ranked source IDs must be a sequence")
        if any(not isinstance(source_id, str) or not source_id for source_id in ids):
            raise ValueError("Ranked source IDs must be non-empty strings")
        ordered[module] = ids
    if set(active) - ordered.keys():
        raise ValueError("An active module ranking is missing")
    selected, seen = [], set()
    for rank in range(max((len(ordered[module]) for module in active), default=0)):
        for module in active:
            ids = ordered[module]
            if rank >= len(ids) or ids[rank] in seen:
                continue
            if len(selected) == top_k:
                break
            selected.append(ids[rank])
            seen.add(ids[rank])
        if len(selected) == top_k:
            break
    fallback = not documented_modules
    return {
        "source_ids": selected,
        "documented_modules": documented_modules,
        "unmeasured_modules": unmeasured_modules,
        "policy": {
            "name": "documented_modules_round_robin_v1",
            "fallback_to_all_requested": fallback,
            "rationale": (
                "No requested module has a documented fact; allocate across all requested modules."
                if fallback
                else "Allocate only across requested modules with documented facts; unmeasured modules remain unresolved."
            ),
        },
    }

