retrieval/discovery.py.content:
"""Symptom-led module discovery alongside mandatory rule-bound source citations."""

from occupational_fitness_rag.retrieval.engine import RetrievalEngine
from occupational_fitness_rag.settings import RetrievalSettings


def discover_symptoms(retriever, result, rules):
    groups = {}
    for request in result.rag_requests:
        module = rules[request.rule_id]["module"]
        for span in result.narrative_context.get(request.request_id, []):
            groups.setdefault(module, {})[(span.start, span.end)] = span
    reports = []
    engine = RetrievalEngine(retriever.store, RetrievalSettings(top_k=5))
    for module, positions in sorted(groups.items()):
        spans = sorted(positions.values(), key=lambda s: s.start)
        query = " ".join(s.quote for s in spans)[:6000]
        filters = {
            "module": module,
            "licence_context": "commercial",
            "source_version": "AP-G56-22",
            "index_sha256": retriever.workflow.catalogue.index_sha256,
        }
        hits = engine.retrieve(query, filters)
        ranked, citations, seen = [], [], set()
        for rank, hit in enumerate(hits, 1):
            if any(str(hit.doc.metadata.get(k)) != v for k, v in filters.items()):
                raise ValueError("Symptom retrieval crossed its module/version boundary")
            source_ids = hit.doc.metadata["source_ids_csv"].split(",")
            ranked.append(
                {
                    "rank": rank,
                    "chunk_id": hit.doc.chunk_id,
                    "source_ids": source_ids,
                    "fusion_score": hit.score,
                    "vector_score": hit.vector_score,
                    "bm25_score": hit.bm25_score,
                }
            )
            for sid in source_ids:
                if sid not in seen:
                    citations.append(
                        retriever.workflow.catalogue.citation(
                            sid, hit.score, "retrieval_rank"
                        ).model_dump(mode="json")
                    )
                    seen.add(sid)
        reports.append(
            {
                "module": module,
                "query": query,
                "query_mode": "joined_verbatim_symptom_spans",
                "source_text_sha256": result.narrative_source_text_sha256,
                "source_passages": [s.model_dump(mode="json") for s in spans],
                "metadata_filters": filters,
                "ranked_candidates": ranked,
                "citations": citations,
                "status": "candidates_found" if ranked else "no_candidates",
                "clinical_facts_inferred": False,
            }
        )
    return reports

retrieval/engine.py.content:
from __future__ import annotations

from occupational_fitness_rag.indexing.base import VectorStore
from occupational_fitness_rag.settings import RetrievalSettings

from .bm25 import rank_bm25
from .fusion import FusedResult, reciprocal_rank_fusion
from .reranker import CrossEncoderReranker, NoOpReranker


class RetrievalEngine:
    def __init__(self, store: VectorStore, settings: RetrievalSettings):
        self.store = store
        self.settings = settings
        if settings.reranker == "cross_encoder":
            self.reranker = CrossEncoderReranker(settings.cross_encoder_model)
        else:
            self.reranker = NoOpReranker()

    def retrieve(self, query: str, filters: dict[str, str]) -> list[FusedResult]:
        # HARD boundary: metadata filtering is supplied to the vector search itself.
        vector_ranked = (
            self.store.search(query, filters, self.settings.candidate_k)
            if self.settings.use_vector
            else []
        )

        bm25_ranked = []
        if self.settings.use_bm25:
            filtered = self.store.get_filtered(filters, self.settings.max_filtered_documents)
            bm25_ranked = rank_bm25(query, filtered, self.settings.bm25_k)

        if self.settings.use_bm25:
            fused = reciprocal_rank_fusion(vector_ranked, bm25_ranked, self.settings.rrf_k)
        else:
            fused = [
                FusedResult(
                    doc=doc, score=float(doc.vector_score or 0.0), vector_score=doc.vector_score
                )
                for doc in vector_ranked
            ]

        reranked = self.reranker.rerank(query, fused)

        # Deduplicate by chunk ID while preserving rank.
        seen: set[str] = set()
        unique: list[FusedResult] = []
        for item in reranked:
            if item.doc.chunk_id in seen:
                continue
            seen.add(item.doc.chunk_id)
            unique.append(item)
            if len(unique) >= self.settings.top_k:
                break
        return unique

retrieval/fusion.py.content:
from __future__ import annotations

from dataclasses import dataclass, field

from occupational_fitness_rag.indexing.base import StoredDocument


@dataclass
class FusedResult:
    doc: StoredDocument
    score: float
    vector_score: float | None = None
    bm25_score: float | None = None
    rerank_score: float | None = None
    graph_paths: list[str] = field(default_factory=list)


def reciprocal_rank_fusion(
    vector_ranked: list[StoredDocument],
    bm25_ranked: list[tuple[StoredDocument, float]],
    rrf_k: int = 60,
) -> list[FusedResult]:
    by_id: dict[str, FusedResult] = {}
    for rank, doc in enumerate(vector_ranked, start=1):
        item = by_id.setdefault(doc.chunk_id, FusedResult(doc=doc, score=0.0))
        item.score += 1.0 / (rrf_k + rank)
        item.vector_score = doc.vector_score
    for rank, (doc, raw_score) in enumerate(bm25_ranked, start=1):
        item = by_id.setdefault(doc.chunk_id, FusedResult(doc=doc, score=0.0))
        item.score += 1.0 / (rrf_k + rank)
        item.bm25_score = raw_score
    return sorted(by_id.values(), key=lambda x: x.score, reverse=True)

retrieval/graph.py.content:
"""Experimental rule/source graph expansion over the existing verified anchors.

This is a small graph-assisted retrieval baseline, not a full-document GraphRAG
system. It does not infer diagnoses or change the production RAG configuration.
"""

from __future__ import annotations

from collections import defaultdict

from occupational_fitness_rag.retrieval.fusion import FusedResult


def expand_graph(seeds, filtered_documents, book, catalogue, module, top_k):
    """Rank seed hits and one-hop neighbours with fixed, inspectable edge weights."""
    docs = {doc.chunk_id: doc for doc in filtered_documents}
    source_to_chunks = defaultdict(set)
    for doc in filtered_documents:
        for source_id in doc.metadata["source_ids_csv"].split(","):
            if source_id not in catalogue.units:
                raise ValueError("Graph chunk contains an unknown source ID")
            source_to_chunks[source_id].add(doc.chunk_id)
    edges = defaultdict(dict)

    def connect(left, right, weight):
        if left != right and left in source_to_chunks and right in source_to_chunks:
            edges[left][right] = max(edges[left].get(right, 0), weight)
            edges[right][left] = max(edges[right].get(left, 0), weight)

    for rule in book.rules:
        if rule["module"] != module:
            continue
        sources = rule["source_ids"]
        for left in sources:
            for right in sources:
                connect(left, right, 0.85)
    for source_id in source_to_chunks:
        unit = catalogue.units[source_id]
        for other in unit["cross_references"]:
            connect(source_id, other, 0.85)
        for other in source_to_chunks:
            if unit["section"] == catalogue.units[other]["section"]:
                connect(source_id, other, 0.45)

    scores = defaultdict(float)
    direct = {}
    for rank, hit in enumerate(seeds[:3], 1):
        if hit.doc.chunk_id not in docs:
            raise ValueError("Graph seed crossed its metadata filter")
        direct[hit.doc.chunk_id] = hit
        vote = 1.0 / (60 + rank)
        scores[hit.doc.chunk_id] += vote
        for source_id in hit.doc.metadata["source_ids_csv"].split(","):
            for neighbour, weight in edges[source_id].items():
                for chunk_id in source_to_chunks[neighbour]:
                    scores[chunk_id] += vote * weight
    ranked = sorted(scores, key=lambda chunk_id: (-scores[chunk_id], chunk_id))[:top_k]
    return [
        FusedResult(
            doc=docs[chunk_id],
            score=scores[chunk_id],
            vector_score=direct[chunk_id].vector_score if chunk_id in direct else None,
            bm25_score=direct[chunk_id].bm25_score if chunk_id in direct else None,
        )
        for chunk_id in ranked
    ]

retrieval/graph_local.py.content:
"""Experimental query-aware source/rule graph ranking over verified anchors.

The graph contains only existing catalogue sources, rule links and section links.
It has no LLM-extracted entities or community reports and is not full GraphRAG.
It never changes production rule outcomes or source quotations.
"""

from __future__ import annotations

import math
import re
from collections import defaultdict

from occupational_fitness_rag.retrieval.fusion import FusedResult

_STOP = {
    "a", "an", "and", "are", "as", "at", "be", "by", "commercial", "diabetes",
    "driver", "driving", "for", "from", "has", "he", "her", "his", "in", "is",
    "licence", "nurse", "of", "on", "or", "patient", "she", "the", "to", "was",
    "were", "with", "blackout", "hearing", "hypertension", "vision",
}


def graph_manifest(book, catalogue):
    """Export the rule/source/section graph for provenance and clinical review."""
    nodes, edges = {}, set()
    for source_id, unit in catalogue.units.items():
        nodes[f"source:{source_id}"] = {
            "type": "verified_source",
            "source_id": source_id,
            "section": unit["section"],
            "pdf_page": unit["pdf_page"],
            "table_row": unit["table_row"],
        }
        section = f"section:{unit['section']}"
        nodes.setdefault(section, {"type": "guideline_section", "section": unit["section"]})
        edges.add((section, f"source:{source_id}", "contains_source"))
        for other in unit["cross_references"]:
            if other not in catalogue.units:
                raise ValueError("Graph cross-reference names an unknown source")
            edges.add((f"source:{source_id}", f"source:{other}", "catalogue_reference"))
    for rule in book.rules:
        rule_node = f"rule:{rule['rule_id']}"
        nodes[rule_node] = {
            "type": "rule",
            "module": rule["module"],
            "subcondition": rule.get("subcondition"),
        }
        for source_id in rule["source_ids"]:
            if source_id not in catalogue.units:
                raise ValueError("Graph rule names an unknown source")
            edges.add((rule_node, f"source:{source_id}", "cites_source"))
    return {
        "schema_version": "1.0.0",
        "graph_type": "curated_rule_source_section_graph",
        "full_graphrag": False,
        "clinical_review_status": "pending",
        "index_sha256": catalogue.index_sha256,
        "ruleset_sha256": book.sha256,
        "nodes": [{"id": node_id, **nodes[node_id]} for node_id in sorted(nodes)],
        "edges": [
            {"from": left, "to": right, "kind": kind}
            for left, right, kind in sorted(edges)
        ],
    }


def _terms(text):
    # Keep "non-insulin" distinct from insulin; split other clinical compounds.
    text = re.sub(r"\bnon[- ]insulin\b", "noninsulin", text.lower())
    return {
        token
        for token in re.findall(r"[a-z0-9]+", text)
        if len(token) >= 3 and token not in _STOP
    }


def expand_local_graph(seeds, filtered_documents, book, catalogue, module, query, top_k):
    """Combine query-to-rule/source matches with inspectable graph paths."""
    source_docs = {}
    for doc in filtered_documents:
        for source_id in doc.metadata["source_ids_csv"].split(","):
            if source_id not in catalogue.units or doc.metadata["module"] != module:
                raise ValueError("Graph source crossed its verified module boundary")
            source_docs[source_id] = doc
    if not source_docs:
        return []
    query_terms = _terms(query)
    scores = defaultdict(float)
    paths = defaultdict(set)
    seed_by_chunk = {hit.doc.chunk_id: hit for hit in seeds}
    for rank, hit in enumerate(seeds, 1):
        if hit.doc.chunk_id not in {doc.chunk_id for doc in filtered_documents}:
            raise ValueError("Graph seed crossed its metadata filter")
        for source_id in hit.doc.metadata["source_ids_csv"].split(","):
            scores[source_id] += 0.8 / math.sqrt(rank)
            paths[source_id].add(f"hybrid_seed_rank:{rank}")
    for source_id in source_docs:
        unit = catalogue.units[source_id]
        title_matches = query_terms & _terms(unit["table_row"] or "")
        evidence_matches = query_terms & _terms(unit["evidence_text"])
        if title_matches:
            scores[source_id] += min(0.42, 0.16 * len(title_matches))
            paths[source_id].add("source_title:" + ",".join(sorted(title_matches)))
        if evidence_matches:
            scores[source_id] += min(0.12, 0.025 * len(evidence_matches))
            paths[source_id].add("source_text_terms:" + ",".join(sorted(evidence_matches)))
    neighbours = defaultdict(dict)

    def connect(left, right, weight, reason):
        if left == right or left not in source_docs or right not in source_docs:
            return
        if weight > neighbours[left].get(right, (0, ""))[0]:
            neighbours[left][right] = (weight, reason)
            neighbours[right][left] = (weight, reason)

    for rule in book.rules:
        if rule["module"] != module:
            continue
        sources = [source_id for source_id in rule["source_ids"] if source_id in source_docs]
        matched = query_terms & _terms(
            " ".join((rule.get("subcondition") or "", rule.get("rag_query_key") or ""))
        )
        if matched:
            for source_id in sources:
                scores[source_id] += min(0.36, 0.18 * len(matched))
                paths[source_id].add(
                    f"rule:{rule['rule_id']}:" + ",".join(sorted(matched))
                )
        for left in sources:
            for right in sources:
                connect(left, right, 0.70, f"shared_rule:{rule['rule_id']}")
    for source_id in source_docs:
        unit = catalogue.units[source_id]
        for other in unit["cross_references"]:
            connect(source_id, other, 0.9, f"catalogue_reference:{source_id}")
        for other in source_docs:
            if unit["section"] == catalogue.units[other]["section"]:
                connect(source_id, other, 0.22, f"same_section:{unit['section']}")
    direct = dict(scores)
    for source_id, value in direct.items():
        for neighbour, (weight, reason) in neighbours[source_id].items():
            scores[neighbour] += 0.12 * weight * value
            paths[neighbour].add(reason)
    # Unit-level comparison has one source per chunk. Aggregate defensively for
    # grouped units while preserving exactly the filtered source documents.
    chunk_scores = defaultdict(float)
    chunk_paths = defaultdict(set)
    docs_by_chunk = {doc.chunk_id: doc for doc in filtered_documents}
    for source_id, value in scores.items():
        chunk_id = source_docs[source_id].chunk_id
        chunk_scores[chunk_id] = max(chunk_scores[chunk_id], value)
        chunk_paths[chunk_id].update(paths[source_id])
    ranked = sorted(chunk_scores, key=lambda key: (-chunk_scores[key], key))[:top_k]
    return [
        FusedResult(
            doc=docs_by_chunk[chunk_id],
            score=chunk_scores[chunk_id],
            vector_score=(
                seed_by_chunk[chunk_id].vector_score if chunk_id in seed_by_chunk else None
            ),
            bm25_score=(seed_by_chunk[chunk_id].bm25_score if chunk_id in seed_by_chunk else None),
            graph_paths=sorted(chunk_paths[chunk_id]),
        )
        for chunk_id in ranked
    ]

